ALTER TABLE "stored_files" DROP CONSTRAINT "stored_files_ready_check";--> statement-breakpoint
ALTER TABLE "stored_files" ADD CONSTRAINT "stored_files_ready_check" CHECK ("stored_files"."status" <> 'ready' OR ("stored_files"."content_type" IS NOT NULL AND "stored_files"."sha256" IS NOT NULL AND "stored_files"."sha256" ~ '^[a-f0-9]{64}$' AND (("stored_files"."purpose" = 'avatar' AND "stored_files"."content_type" ~ '^image/[a-z0-9][a-z0-9.+-]*$' AND "stored_files"."content_type" <> 'image/svg+xml') OR ("stored_files"."purpose" = 'gpx' AND "stored_files"."content_type" = 'application/gpx+xml'))));